// 1. Define the GraphQL Mutation
const CREATE_USER_MUTATION = `
  mutation CreateUser($input: CreateUserInput!) {
    createUser(input: $input) {
      id
      email
      name
    }
  }
`;

// 2. The Component
export const UserRegistrationForm = () => {
  const [createUser, { loading, error }] = useMutation(CREATE_USER_MUTATION);

  const onSubmit = async (data) => {
    try {
      // 3. Prepare variables for the mutation
      // Ensure data matches the input type defined in your GraphQL schema
      const variables = {
        input: {
          email: data.email,
          name: data.name,
          // Add other fields here
        }
      };

      // 4. Execute the mutation
      const result = await createUser({ variables });

      // 5. Handle Success
      console.log('User created successfully:', result.data.createUser);
      toast.success('User account created!');

      // Reset form or redirect
      // resetForm(); 
    } catch (err) {
      // 6. Handle Errors
      console.error('GraphQL Error:', err);

      // Extract the message from the error object if available
      const errorMessage = err.message || 'Something went wrong.';
      toast.error(errorMessage);
    }
  };

  return (
    <form onSubmit={(e) => {
      e.preventDefault();
      // Trigger the submit logic
      onSubmit({ email: 'test@example.com', name: 'John Doe' }); 
    }}>
      {/* Form fields would go here */}
      <button type="submit" disabled={loading}>
        {loading ? 'Creating...' : 'Create Account'}
      </button>
    </form>
  );
};
```

