            background-color: #e0e0e0;
        }
    </style>
</head>
<body>
    <table id="sortableTable">
        <thead>
            <tr>
                <th draggable="true">Name</th>
                <th draggable="true">Age</th>
                <th draggable="true">City</th>
            </tr>
        </thead>
        <tbody>
            <tr>
                <td>John Doe</td>
                <td>30</td>
                <td>New York</td>
            </tr>
            <tr>
                <td>Jane Smith</td>
                <td>25</td>
                <td>Los Angeles</td>
            </tr>
            <tr>
                <td>Bob Johnson</td>
                <td>35</td>
                <td>Chicago</td>
            </tr>
        </tbody>
    </table>

    <script>
        const table = document.getElementById('sortableTable');
        const headers = table.querySelectorAll('th[draggable="true"]');

        headers.forEach(header => {
            header.addEventListener('dragstart', function(e) {
                this.classList.add('dragging');
                e.dataTransfer.effectAllowed = 'move';
            });

            header.addEventListener('dragend', function() {
                this.classList.remove('dragging');
            });
        });

        table.addEventListener('dragover', function(e) {
            e.preventDefault();
            e.dataTransfer.dropEffect = 'move';
        });

        table.addEventListener('drop', function(e) {
            e.preventDefault();
            const draggedHeader = document.querySelector('.dragging');
            const targetHeader = e.target.closest('th');

            if (draggedHeader && targetHeader) {
                const draggedIndex = Array.from(headers).indexOf(draggedHeader);
                const targetIndex = Array.from(headers).indexOf(targetHeader);

                if (draggedIndex !== targetIndex) {
                    const headersArray = Array.from(headers);
                    headersArray.splice(draggedIndex, 1);
                    headersArray.splice(targetIndex, 0, draggedHeader);
                    headersArray.forEach((header, index) => {
                        header.style.order = index;
                    });
                }
            }
        });
    </script>
</body>
</html>
```

