// This function handles the logic: Case-insensitive search, partial matching, and sorting by relevance
const searchHotels = async (query) => {
  if (!query || query.length < 2) return [];

  const client = await pool.connect();
  try {
    // We use ILIKE for case-insensitive partial matching
    // We order by name first, then by rating to show best matches first
    const result = await client.query(
      `SELECT * FROM hotels 
       WHERE name ILIKE $1 
       ORDER BY name ASC, rating DESC`,
      [`%${query}%`]
    );
    return result.rows;
  } finally {
    client.release();
  }
};

