	Email  string `yaml:"email"`
	Domains []string `yaml:"domains"`
}

type Config struct {
	Credentials map[string]Credentials `yaml:"credentials"`
}

// GoogleDomainsSolver implements the dns01.ChallengeSolver interface
type GoogleDomainsSolver struct {
	config Config
	client *http.Client
}

// NewGoogleDomainsSolver creates a new solver instance
func NewGoogleDomainsSolver(configPath string) (*GoogleDomainsSolver, error) {
	var config Config
	data, err := os.ReadFile(configPath)
	if err != nil {
		return nil, fmt.Errorf("failed to read credentials file: %w", err)
	}

	if err := yaml.Unmarshal(data, &config); err != nil {
		return nil, fmt.Errorf("failed to parse credentials file: %w", err)
	}

	return &GoogleDomainsSolver{
		config: config,
		client: &http.Client{Timeout: 2 * time.Minute},
	}, nil
}

// GetChallengeSolver returns the solver for a specific domain
func (s *GoogleDomainsSolver) GetChallengeSolver(domain string) (dns01.ChallengeSolver, error) {
	// Find the credential set that matches the domain
	// We look for an exact match or a wildcard match
	var cred Credentials
	found := false

	for name, c := range s.config.Credentials {
		for _, d := range c.Domains {
			if d == domain || strings.HasPrefix(d, "*.") && strings.HasSuffix(d, "."+domain) {
				cred = c
				found = true
				break
			}
