		return nil, fmt.Errorf("no credentials found for domain: %s", domain)
	}

	return &googleDomainsSolverImpl{
		apiKey:  cred.APIKey,
		email:   cred.Email,
		domain:  domain,
		client:  s.client,
	}, nil
}

